const lessons=[{"sentences":[{"speaker":"A","text":"Welcome everyone to our planning meeting for the upcoming summer market.","position":1,"audioStartSeconds":0,"audioEndSeconds":4.618416666666667},{"speaker":"A","text":"This year the event will take place at the central park on the first Saturday of July.","position":2,"audioStartSeconds":4.818416666666667,"audioEndSeconds":10.076916666666667},{"speaker":"A","text":"Local vendors can rent a standard stall for forty pounds for the entire day.","position":3,"audioStartSeconds":10.276916666666667,"audioEndSeconds":15.264},{"speaker":"A","text":"Each stall includes one large table and two folding chairs under a waterproof canopy.","position":4,"audioStartSeconds":15.464,"audioEndSeconds":20.9795},{"speaker":"A","text":"If you plan to sell hot food items you must bring your own portable generator.","position":5,"audioStartSeconds":21.1795,"audioEndSeconds":26.1795},{"speaker":"A","text":"Parking for stall holders is available behind the community library until eight in the morning.","position":6,"audioStartSeconds":26.3795,"audioEndSeconds":32.25575},{"speaker":"A","text":"Public visitors should use the underground station because the main street will be closed to cars.","position":7,"audioStartSeconds":32.45575,"audioEndSeconds":38.17666666666667},{"speaker":"A","text":"Volunteers must gather near the main fountain at nine to collect their name badges.","position":8,"audioStartSeconds":38.376666666666665,"audioEndSeconds":43.49341666666667},{"speaker":"A","text":"Free drinking water will be provided inside the main information tent all afternoon.","position":9,"audioStartSeconds":43.693416666666664,"audioEndSeconds":49.260416666666664},{"speaker":"A","text":"Please remember to submit your completed insurance forms before Friday afternoon.","position":10,"audioStartSeconds":49.46041666666667,"audioEndSeconds":54.61429166666667},{"speaker":"A","text":"We will also have a special recycling station located next to the entrance gates.","position":11,"audioStartSeconds":54.81429166666667,"audioEndSeconds":60.278958333333335},{"speaker":"A","text":"All participants must ensure their rubbish is properly sorted before leaving the grounds.","position":12,"audioStartSeconds":60.47895833333333,"audioEndSeconds":66.07058333333333},{"speaker":"A","text":"Any extra tables can be requested at the office before the end of this week.","position":13,"audioStartSeconds":66.27058333333333,"audioEndSeconds":71.10420833333333},{"speaker":"A","text":"Thank you all for your continuous support and dedication to making this market successful.","position":14,"audioStartSeconds":71.30420833333334,"audioEndSeconds":76.94404166666666}],"questions":[{"prompt":"Event venue: ______","answer":"central park","evidenceSentence":2,"evidence":"central park","explanation":"Người nói cho biết sự kiện diễn ra ở công viên trung tâm ('central park')."},{"prompt":"Standard stall price: ______ pounds","answer":"forty","evidenceSentence":3,"evidence":"forty pounds","explanation":"Giá thuê quầy tiêu chuẩn là bốn mươi bảng ('forty pounds')."},{"prompt":"Hot food vendors need a: ______","answer":"generator","evidenceSentence":5,"evidence":"portable generator","explanation":"Người bán đồ ăn nóng cần mang theo máy phát điện ('portable generator')."},{"prompt":"Parking location for holders: ______ library","answer":"community","evidenceSentence":6,"evidence":"community library","explanation":"Bãi đậu xe cho người bán hàng nằm phía sau thư viện cộng đồng ('community library')."},{"prompt":"Meeting spot for volunteers: ______ fountain","answer":"main","evidenceSentence":8,"evidence":"main fountain","explanation":"Tình nguyện viên tập trung gần đài phun nước chính ('main fountain')."},{"prompt":"Deadline for insurance forms: ______ afternoon","answer":"Friday","evidenceSentence":10,"evidence":"Friday afternoon","explanation":"Hạn chót nộp giấy tờ bảo hiểm là chiều thứ Sáu ('Friday afternoon')."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
